-- pre-data: everything the load needs to exist before it starts.
--
-- The module's default target_table_prep_mode is DO_NOTHING, so DMS creates
-- none of this. A missing table does not fail the task - it suspends that one
-- table, which reads as a partial success.
--
-- Generated by the schema conversion step, reviewed, then committed here.

CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS dms_control;

-- Tables only. No indexes, no foreign keys, no triggers: those are post-data,
-- because building them during the load costs throughput and rejects rows that
-- arrive parent-last.
CREATE TABLE IF NOT EXISTS core.account (
  account_id      bigint        NOT NULL,
  customer_id     bigint        NOT NULL,
  opened_on       date          NOT NULL,
  status          varchar(16)   NOT NULL,
  balance_minor   bigint        NOT NULL
);

CREATE TABLE IF NOT EXISTS core.customer (
  customer_id     bigint        NOT NULL,
  full_name       varchar(200)  NOT NULL,
  created_on      timestamptz   NOT NULL
);
